test('applyVoucher does not mutate original invoice', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  assert.equal(result.ok, true);
  const invoice = result.value;
  const invoiceCopy = JSON.parse(JSON.stringify(invoice));
  applyVoucher(invoice, { code: 'SAVE10', amount: 10000 });
  assert.deepEqual(invoice, invoiceCopy);
});

test('invoiceTotals includes voucher in calculation', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  assert.equal(result.ok, true);
  let invoice = result.value;
  const voucherResult = applyVoucher(invoice, { code: 'SAVE10', amount: 10000 });
  assert.equal(voucherResult.ok, true);
  invoice = voucherResult.value;

  const totals = invoiceTotals(invoice);
  assert.deepEqual(totals, {
    subtotal: 95000,
    discount: 0,
    vat: 19950,
    voucher: 10000,
    total: 104950,
  });
});

