test('voucher is preserved through invoice operations', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  assert.equal(result.ok, true);
  let invoice = result.value;

  const voucherResult = applyVoucher(invoice, { code: 'SAVE10', amount: 10000 });
  assert.equal(voucherResult.ok, true);
  invoice = voucherResult.value;
  assert.equal(invoice.voucher.code, 'SAVE10');

  const issued = issueInvoice(invoice, []);
  assert.equal(issued.ok, true);
  assert.equal(issued.value.voucher.code, 'SAVE10');
  assert.equal(issued.value.voucher.amount, 10000);
});

